<?php
namespace App\Http\Controllers\Admin;use App\Domain\Industries\IndustryRegistry;use App\Http\Controllers\Controller;use App\Models\{Industry,IndustryChallenge,IndustryNeed,IndustryOutcome,IndustryUseCase};use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;class IndustryChildController extends Controller{private const MAP=['challenges'=>IndustryChallenge::class,'outcomes'=>IndustryOutcome::class,'needs'=>IndustryNeed::class,'use-cases'=>IndustryUseCase::class];public function store(Request $r,Industry $industry,string $type):RedirectResponse{$class=$this->class($type);$relation=$this->relation($type);$max=IndustryRegistry::CHILDREN[$relation];if($industry->{$relation}()->count()>=$max){throw ValidationException::withMessages([$type=>"A maximum of $max records is allowed."]);}$data=$this->data($r);$data['display_order']=(int)$industry->{$relation}()->max('display_order')+1;$industry->{$relation}()->create($data);return back()->with('status','Structured item added.');}public function update(Request $r,Industry $industry,string $type,int $child):RedirectResponse{$this->owned($industry,$type,$child)->update($this->data($r));return back()->with('status','Structured item saved.');}public function destroy(Industry $industry,string $type,int $child):RedirectResponse{$this->owned($industry,$type,$child)->delete();$this->normalize($industry,$type);return back()->with('status','Structured item removed.');}public function move(Request $r,Industry $industry,string $type,int $child):RedirectResponse{$model=$this->owned($industry,$type,$child);$direction=$r->validate(['direction'=>['required','in:up,down']])['direction'];$class=$this->class($type);DB::transaction(function()use($model,$class,$direction,$industry,$type){$peer=$class::where('industry_id',$industry->id)->where('display_order',$direction==='up'?'<':'>',$model->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$model->display_order;$model->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}$this->normalize($industry,$type);});return back();}private function data(Request $r):array{return $r->validate(['title'=>['required','string','max:160'],'description'=>['required','string','max:5000'],'icon'=>['nullable',Rule::in(IndustryRegistry::ICONS)],'is_active'=>['boolean']]);}private function class(string $type):string{return self::MAP[$type]??abort(404);}private function relation(string $type):string{return $type==='use-cases'?'useCases':$type;}private function owned(Industry $industry,string $type,int $id){return $this->class($type)::where('industry_id',$industry->id)->findOrFail($id);}private function normalize(Industry $industry,string $type):void{$this->class($type)::where('industry_id',$industry->id)->orderBy('display_order')->orderBy('id')->get()->each(fn($item,$index)=>$item->updateQuietly(['display_order'=>$index+1]));}}
